// Loads the local development addon first, then the matching optional platform package. Kept
// as a small loader instead of napi-rs's generated one; index.d.ts is generated by
// `yarn build:native` (scripts/build-native.mjs). See packages/mcp/DEVELOPING.md.
const { existsSync } = require("node:fs");
const path = require("node:path");
const { createRequire } = require("node:module");
const requireFromHere = createRequire(__filename);

// napi-rs filenames: `freellama.<platform>-<arch>[-<abi>].node`. Linux ships glibc builds, Windows
// MSVC builds; macOS has no ABI suffix.
const ABI_SUFFIX = { linux: "-gnu", win32: "-msvc" }[process.platform] ?? "";
const id = `${process.platform}-${process.arch}${ABI_SUFFIX}`;
const localAddon = path.join(__dirname, `freellama.${id}.node`);
const packageName = `@octocodeai/freellama-native-${id}`;

if (existsSync(localAddon)) {
  module.exports = require(localAddon);
} else {
  try {
    module.exports = requireFromHere(packageName);
  } catch (error) {
    throw new Error(
      `freellama: no usable native addon for ${process.platform}-${process.arch}.\n` +
        `Tried ${localAddon} and the optional package ${packageName}.\n` +
        "Reinstall without --omit=optional. From a source checkout, run `yarn build:native`.\n" +
        `Load failure: ${error?.message ?? error}`,
    );
  }
}
